package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Inert configuration and private backup/storage only. AlarmActivity is never opened. */
public class GradedMathConfigurationTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private AlarmEditorActivity activity;
    private UiObject2 object(String desc)throws Exception{UiObject2 found=device.wait(Until.findObject(By.desc(desc)),2000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue("Scrollable route for "+desc,scroll.exists());scroll.scrollIntoView(new UiSelector().description(desc));found=device.wait(Until.findObject(By.desc(desc)),3000);}assertNotNull(desc,found);return found;}
    private void click(String text)throws Exception{UiObject2 found=device.wait(Until.findObject(By.text(text)),2000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(text,scroll.exists());scroll.scrollIntoView(new UiSelector().text(text));found=device.wait(Until.findObject(By.text(text)),3000);}assertNotNull(text,found);found.click();device.waitForIdle();}
    private void pick(String setting,String value)throws Exception{object(setting).click();assertTrue(device.wait(Until.hasObject(By.desc("Options for "+setting)),3000));object(value).click();assertTrue(device.wait(Until.gone(By.desc("Options for "+setting)),3000));device.waitForIdle();}
    private void launch(Alarm alarm)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Edit alarm")),5000));}
    private void recreate(String title)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(title,device.wait(Until.hasObject(By.text(title)),5000));}
    private void capture(String suffix)throws Exception{CountDownLatch frame=new CountDownLatch(1);long until=SystemClock.elapsedRealtime()+5000;boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused math configuration window",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));if(!suffix.equals("ordered"))i.runOnMainSync(()->{for(String operator:List.of("Addition","Subtraction","Multiplication","Division")){ArrayList<View> tiles=new ArrayList<>();activity.getWindow().getDecorView().findViewsWithText(tiles,operator,View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);assertEquals(operator+" has one operator card",1,tiles.size());View tile=tiles.get(0),parent=(View)tile.getParent();assertTrue(operator+" upper border stays inside its row",tile.getTop()>=parent.getPaddingTop());assertTrue(operator+" lower border stays inside its row",tile.getBottom()<=parent.getHeight()-parent.getPaddingBottom());}});File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"math-config-"+suffix+".png")));}
    @Test public void perTaskGradeOperatorsTypedModeCancelRecreatePersistAndBadImportsStayInert()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        String name="math-config-"+UUID.randomUUID()+".db";Map<String,?> originalPrefs=new HashMap<>(Prefs.of(c).getAll());Records.Factory oldRecords=Records.factory;AlarmScheduling.Port oldScheduling=AlarmScheduling.port;int[] schedules={0};List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertTrue("No alarm or output activity",a instanceof AlarmEditorActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);
        try{
            i.runOnMainSync(()->{Records.factory=context->new Store(context,name);AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){assertFalse(alarm.enabled);schedules[0]++;}};});
            Alarm legacy=new Alarm(1);legacy.enabled=false;legacy.label="Math configuration fixture";legacy.difficulty=3;Alarm other=new Alarm(2);other.enabled=false;other.label="Preserved other alarm";String untouched=other.json().toString();try(Store store=new Store(c,name)){store.save(legacy);store.save(other);}assertFalse(legacy.json().has("routine"));launch(legacy);click("Challenges");object("Edit task 1 Math").click();assertTrue(object("Medium").isSelected());assertTrue(object("Addition").isChecked());assertFalse(object("Subtraction").isChecked());assertTrue(object("Choices").isSelected());capture("default");object("Hard").click();object("Back").click();object("Edit task 1 Math").click();assertTrue("Cancel preserves original grade",object("Medium").isSelected());object("Back").click();
            object("Configure Math").click();object("Hard").click();for(String operator:List.of("Subtraction","Multiplication","Division"))object(operator).click();object("Addition").click();assertFalse(object("Addition").isChecked());assertTrue(object("Division").isChecked());capture("operators");pick("Rounds","2 rounds");object("Type answer").click();assertTrue(object("Type answer").isSelected());capture("typed");recreate("Use Math");assertTrue(object("Hard").isSelected());assertTrue(object("Type answer").isSelected());assertFalse(object("Addition").isChecked());for(String operator:List.of("Subtraction","Multiplication","Division"))assertTrue(object(operator).isChecked());capture("recreated");object("Rounds").click();assertTrue(device.wait(Until.hasObject(By.desc("Options for Rounds")),3000));recreate("Rounds");assertTrue(object("2 rounds").isChecked());click("Cancel");assertTrue(device.wait(Until.gone(By.desc("Options for Rounds")),3000));click("Use Math");assertNotNull(object("Edit task 2 Math"));capture("ordered");click("Save routine");try(Store store=new Store(c,name)){assertFalse(store.alarm(1).json().has("routine"));assertEquals(untouched,store.alarm(2).json().toString());}assertEquals(0,schedules[0]);click("Save alarm");long until=SystemClock.elapsedRealtime()+5000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(activity.isDestroyed());
            Alarm saved;try(Store store=new Store(c,name)){saved=store.alarm(1);assertEquals(2,saved.challenges().tasks.size());assertEquals(MathSettings.LEGACY,saved.challenges().tasks.get(0).math);assertEquals(3,saved.challenges().tasks.get(0).rounds);ChallengeRoutine.Task second=saved.challenges().tasks.get(1);assertEquals(new MathSettings(MathSettings.Level.HARD,14,true),second.math);assertEquals(2,second.rounds);assertEquals(5,saved.challenges().units());assertFalse(saved.json().getJSONArray("routine").getJSONObject(0).has("math"));assertEquals("hard",saved.json().getJSONArray("routine").getJSONObject(1).getJSONObject("math").getString("level"));Backup.validate(store.backup());assertEquals(saved.json().toString(),Alarm.read(new JSONObject(saved.json().toString())).json().toString());assertEquals(untouched,store.alarm(2).json().toString());}
            assertEquals(1,schedules[0]);launch(saved);click("Challenges");object("Edit task 2 Math").click();assertTrue(object("Hard").isSelected());assertTrue(object("Type answer").isSelected());assertTrue(object("Division").isChecked());assertFalse(object("Addition").isChecked());capture("reopened");object("Subtraction").click();object("Multiplication").click();object("Division").click();assertTrue(object("Division").isChecked());assertTrue(device.wait(Until.hasObject(By.text("Keep at least one operator selected.")),3000));capture("error");object("Back").click();try(Store store=new Store(c,name)){assertEquals(14,store.alarm(1).challenges().tasks.get(1).math.operators);assertEquals(untouched,store.alarm(2).json().toString());assertBadImportsPreservePrivateDatabase(store,saved,other);}
            assertEquals(originalPrefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"math-config-failure.png"));device.dumpWindowHierarchy(new File(folder,"math-config-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));}finally{app.unregisterActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{Records.factory=oldRecords;AlarmScheduling.port=oldScheduling;});if(owned.stream().allMatch(Activity::isDestroyed))c.deleteDatabase(name);}}
    }
    private void assertBadImportsPreservePrivateDatabase(Store store,Alarm saved,Alarm other)throws Exception{
        JSONObject valid=MathSettingsJson.encode(new MathSettings(MathSettings.Level.HARD,14,true));List<Object> malformed=new ArrayList<>();malformed.add(JSONObject.NULL);malformed.add("hard");malformed.add(new JSONArray());malformed.add(new JSONObject(valid.toString()).put("level",3));malformed.add(new JSONObject(valid.toString()).put("level","nightmare"));malformed.add(new JSONObject(valid.toString()).put("answer",true));malformed.add(new JSONObject(valid.toString()).put("answer","voice"));malformed.add(new JSONObject(valid.toString()).put("operators","+"));malformed.add(new JSONObject(valid.toString()).put("operators",new JSONArray()));malformed.add(new JSONObject(valid.toString()).put("operators",new JSONArray().put("add").put("add")));malformed.add(new JSONObject(valid.toString()).put("operators",new JSONArray().put("add").put(1)));malformed.add(new JSONObject(valid.toString()).put("operators",new JSONArray().put("power")));malformed.add(new JSONObject().put("level","hard"));malformed.add(new JSONObject(valid.toString()).put("unknown",1));String before=store.backup().toString();
        for(Object bad:malformed){JSONArray tasks=ChallengeRoutineJson.encode(saved.challenges());tasks.getJSONObject(1).put("math",bad);JSONObject source=saved.json().put("routine",tasks);Alarm retained=Alarm.read(source);assertTrue(retained.routineInvalid);assertEquals(tasks.toString(),retained.json().getJSONArray("routine").toString());JSONObject backup=store.backup().put("alarms",new JSONArray().put(source).put(other.json()));assertThrows(JSONException.class,()->Backup.restoreData(store,backup));assertEquals(before,store.backup().toString());}
        JSONArray tasks=new JSONArray().put(new JSONObject().put("type","Retype").put("rounds",1).put("math",valid));JSONObject backup=store.backup().put("alarms",new JSONArray().put(saved.json().put("routine",tasks)).put(other.json()));assertThrows(JSONException.class,()->Backup.restoreData(store,backup));assertEquals(before,store.backup().toString());
    }
}
